<?php if(!defined('ABSPATH'))exit;global $wpdb;$t=ICD_Visitas_Database::table('pedagogas');$rows=$wpdb->get_results("SELECT * FROM $t ORDER BY nome");$edit=isset($_GET['edit'])?$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE id=%d",absint($_GET['edit']))):null;$users=get_users(['orderby'=>'display_name']);?>
<div class="wrap icd-admin"><h1>Pedagogas</h1><p>Pedagogas são as profissionais que realizam as visitas de supervisão às escolas.</p><form class="icd-form-grid" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><?php wp_nonce_field('icd_save_pedagoga');?><input type="hidden" name="action" value="icd_save_pedagoga"><input type="hidden" name="id" value="<?php echo (int)($edit->id??0);?>"><label>Nome<input required name="nome" value="<?php echo esc_attr($edit->nome??'');?>"></label><label>E-mail<input type="email" name="email" value="<?php echo esc_attr($edit->email??'');?>"></label><label>Telefone<input name="telefone" value="<?php echo esc_attr($edit->telefone??'');?>"></label><label>Usuário WordPress<select name="wp_user_id"><option value="0">Sem login vinculado</option><?php foreach($users as $u)echo '<option value="'.$u->ID.'" '.selected($edit->wp_user_id??0,$u->ID,false).'>'.esc_html($u->display_name.' ('.$u->user_email.')').'</option>';?></select></label><label class="full">Observações<textarea name="observacoes"><?php echo esc_textarea($edit->observacoes??'');?></textarea></label><?php if($edit):?><label class="icd-check full"><input type="checkbox" name="ativo" <?php checked($edit->ativo);?>> Ativa</label><?php endif;?><button class="button button-primary"><?php echo $edit?'Salvar alterações':'Adicionar pedagoga';?></button></form><table class="widefat striped"><thead><tr><th>Nome</th><th>E-mail</th><th>Telefone</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo esc_html($r->nome);?></td><td><?php echo esc_html($r->email);?></td><td><?php echo esc_html($r->telefone);?></td><td><a href="<?php echo esc_url(admin_url('admin.php?page=icd-visitas-pedagogas&edit='.$r->id));?>">Editar</a></td></tr><?php endforeach;?></tbody></table></div>
